cells={(r,c) for r,row in enumerate([[0,8,8,0,8,8,0],[8,8,8,8,8,8,0],[0,8,8,0,8,0,0],[0,0,8,8,8,0,0]]) for c,v in enumerate(row) if v}
# all placements of 2x2 and L triominoes
from itertools import combinations
shapes=[]
for r in range(7):
 for c in range(7):
  sq={(r+i,c+j) for i in range(2) for j in range(2)}
  if sq<=cells: shapes.append(('sq',sq))
  for missing in [(0,0),(0,1),(1,0),(1,1)]:
   s={(r+i,c+j) for i in range(2) for j in range(2)}-{(r+missing[0],c+missing[1])}
   if s<=cells: shapes.append((f'L{missing}',s))
sol=[]
def rec(rem, chosen):
 if not rem:
  sol.append(chosen); return
 x=min(rem)
 for t,s in shapes:
  if x in s and s<=rem: rec(rem-s,chosen+[(t,s)])
rec(cells,[])
len(sol), [( [(t, sorted(s)) for t,s in a]) for a in sol[:5]]
